### cds view : ZCDS_E3_FI_0012
```abap
@AbapCatalog.sqlViewName: 'ZCDSV_E3_FI_0012'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: '[FI] 외화보유 현황 및 환율 평가 조회'
@Metadata.ignorePropagatedAnnotations: true
@OData.publish: true
define view ZCDS_E3_FI_0012
  with parameters
    P_EVDAT : dats

  as select from    ZCDS_E3_FI_0010(
                       P_EVDAT: $parameters.P_EVDAT ) as b

    left outer join ZCDS_E3_FI_0008                   as e on  e.Fcurr = b.Fwaer
                                                           and e.Erdat = $parameters.P_EVDAT

{
  key b.Hbkid, // 하우스뱅크
  key b.Hktid, // 계좌ID
  key b.Fwaer, // 외화통화

      b.Wrbtr, // 외화잔액
      b.Dmbtr, // 과거 원화금액

      e.Ukurs, // 평가일 환율

      @Semantics.amount.currencyCode: 'Lwaers'
      cast(
          cast( b.Wrbtr as abap.dec(15,2) )
        * cast( e.Ukurs as abap.dec(15,5) )
          as abap.dec(15,2)
      )                      as EvalDmbtr,

      cast( 'KRW' as waers ) as Lwaers

}

```
