```abap
@AbapCatalog.sqlViewName: 'ZCDSV_E3_FI_0010'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: '[FI] 통화별 통장잔액 집계'
@Metadata.ignorePropagatedAnnotations: true
@OData.publish:true
-- 외화보유액 조회
define view ZCDS_E3_FI_0010
  with parameters
    P_EVDAT : dats -- 조회 기준일

  as select from zte3fi0007
{
  key hbkid                  as Hbkid, -- 하우스뱅크 ID
  key hktid                  as Hktid, -- 계좌 ID

      @Semantics.currencyCode: true
  key case fwaer
        when '' then cast( 'KRW' as waers )
        else fwaer
      end                    as Fwaer, -- 통화키 (USD, EUR, JPY, KRW)

      -- 1. 통화별 잔액 합산 (S: 차변(+), H: 대변(-))
      @Semantics.amount.currencyCode: 'Fwaer'
      sum( case shkzg
             when 'S' then wrbtr
             when 'H' then wrbtr * (-1)
           end )             as Wrbtr,

      -- 2. 원화 환산 잔액 합산 (S: 차변(+), H: 대변(-))
      @Semantics.amount.currencyCode: 'Lwaers'
      sum( case shkzg
             when 'S' then dmbtr
             when 'H' then dmbtr * (-1)
           end )             as Dmbtr,

      -- 원화 통화키 참조 필드 (Dmbtr의 통화 속성 정의용)
      cast( 'KRW' as waers ) as Lwaers
}
where
       valut <= :P_EVDAT -- 기준일 이하의 거래 내역만 집계
  and(
       fwaer =  'USD'
    or fwaer =  'EUR'
    or fwaer =  'JPY'
    or fwaer =  ''
  )
group by
  hbkid,
  hktid,
  fwaer -- 대소문자 구분을 위해 원래 테이블 필드인 fwaer로 그룹핑 유지

```
